package com.littlemakers.village.rendercheck;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;
/** Follows the actual child picture menus and verifies renderer motion and village routing. */
public final class Visual32Check extends Instrumentation {
 private Activity activity;private File out;private int captures;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private Object call(Object o,String n,Class<?>[]t,Object...a)throws Exception{Method m=o.getClass().getDeclaredMethod(n,t);m.setAccessible(true);return m.invoke(o,a);}
 private void ui(Runnable r){java.util.concurrent.atomic.AtomicReference<Throwable>failure=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable e){failure.set(e);}});waitForIdleSync();if(failure.get()!=null)throw new AssertionError("UI operation failed",failure.get());}
 private void invoke(String n,Class<?>[]t,Object...a){ui(()->{try{call(activity,n,t,a);}catch(Exception e){throw new RuntimeException(e);}});}
 private Button find(View v,String s){if(v instanceof Button&&s.equals(((Button)v).getText().toString()))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),s);if(b!=null)return b;}return null;}
 private void click(String s){ui(()->{Button b=find(activity.getWindow().getDecorView(),s);if(b==null)throw new AssertionError("Missing picture target "+s);b.performClick();});}
 private interface Condition{boolean ok()throws Exception;}
 private void waitFor(Condition c,String s)throws Exception{long end=SystemClock.uptimeMillis()+30000;while(SystemClock.uptimeMillis()<end){if(c.ok())return;SystemClock.sleep(80);}throw new AssertionError("Timeout "+s);}
 private Activity opened(String name,Runnable action)throws Exception{ActivityMonitor m=addMonitor("com.littlemakers.village.nativeapp."+name,null,false);ui(action);Activity a=waitForMonitorWithTimeout(m,20000);removeMonitor(m);if(a==null)throw new AssertionError("Did not open "+name);waitForIdleSync();return a;}
 private void finishTo(String name)throws Exception{Activity child=activity;ActivityMonitor m=addMonitor("com.littlemakers.village.nativeapp."+name,null,false);ui(child::finish);Activity a=waitForMonitorWithTimeout(m,20000);removeMonitor(m);if(a==null)throw new AssertionError("Did not return to "+name);activity=a;waitForIdleSync();}
 private Object surface()throws Exception{return call(field(activity,"visualMenu"),"surface",new Class[0]);}
 private void liveMenu()throws Exception{waitFor(()->field(activity,"visualMenu")!=null&&surface()!=null&&(Long)field(surface(),"renderedFrames")>2,"live menu meshes");long frames=(Long)field(surface(),"renderedFrames");SystemClock.sleep(220);if((Long)field(surface(),"renderedFrames")<=frames)throw new AssertionError("Preview is static");}
 private void screen(String n)throws Exception{waitForIdleSync();SystemClock.sleep(160);Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new AssertionError("No screenshot");try(FileOutputStream f=new FileOutputStream(new File(out,n+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();captures++;Bundle status=new Bundle();status.putString("case",n);sendStatus(1,status);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  out=new File(getTargetContext().getFilesDir(),"visual32-check");out.mkdirs();getTargetContext().getSharedPreferences("family",0).edit().putString("theme","light").putBoolean("reduce_motion",false).commit();activity=startActivitySync(new Intent().setClassName("com.littlemakers.village","com.littlemakers.village.nativeapp.CreativeActivity").putExtra("destination","play").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();liveMenu();screen("toy-playroom");
  activity=opened("AdventureActivity",()->find(activity.getWindow().getDecorView(),"Village").performClick());waitFor(()->field(activity,"island")!=null&&(Long)field(field(activity,"island"),"renderedFrames")>2,"actual walkable island");screen("actual-village");finishTo("CreativeActivity");activity=opened("AdventureActivity",()->{activity.startActivity(new Intent().setClassName("com.littlemakers.village","com.littlemakers.village.nativeapp.MainActivity").putExtra("destination","world-explorer"));});waitFor(()->field(activity,"island")!=null,"legacy village alias");finishTo("CreativeActivity");
  activity=opened("QuestActivity",()->find(activity.getWindow().getDecorView(),"Adventures").performClick());liveMenu();String[]all={"Number Guardians","Balance Workshop","Robot Routes","Discovery Trail","Letter Adventures","Learning Islands","Little Makers Friends","Shape Builders","Maker World"};for(String name:all)if(find(activity.getWindow().getDecorView(),name)==null)throw new AssertionError("Missing illustrated adventure "+name);screen("toy-adventures");activity=opened("StudioActivity",()->find(activity.getWindow().getDecorView(),"Maker World").performClick());if((Integer)field(field(activity,"state"),"mode")!=5)throw new AssertionError("Picture opens wrong studio");finishTo("QuestActivity");finishTo("CreativeActivity");
  click("Fish");waitFor(()->field(activity,"playScene")!=null&&(Integer)field(field(activity,"playScene"),"program")!=0,"real 3D fish renderer");Object fish=field(activity,"playScene");View water=(View)fish;float before=(Float)field(fish,"fishX");ui(()->{long now=SystemClock.uptimeMillis();MotionEvent e=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,water.getWidth()*.8f,water.getHeight()*.35f,0);water.dispatchTouchEvent(e);e.recycle();e=MotionEvent.obtain(now,now+20,MotionEvent.ACTION_UP,water.getWidth()*.8f,water.getHeight()*.35f,0);water.dispatchTouchEvent(e);e.recycle();});waitFor(()->Math.abs((Float)field(fish,"fishX")-before)>.1,"fish responds to touch");screen("live-fish");invoke("show",new Class[]{String.class},"play");
  activity=opened("QuestActivity",()->find(activity.getWindow().getDecorView(),"Adventures").performClick());activity=opened("MainActivity",()->find(activity.getWindow().getDecorView(),"More puzzles").performClick());liveMenu();if(find(activity.getWindow().getDecorView(),"Parent space")!=null||find(activity.getWindow().getDecorView(),"Privacy policy")!=null)throw new AssertionError("Parent settings still fill child catalog");screen("picture-puzzles");invoke("openGame",new Class[]{String.class,boolean.class},"native-maze-9",true);Object game=field(activity,"gameView");waitFor(()->field(game,"stage")!=null&&(Long)field(field(game,"stage"),"renderedFrames")>2,"maze mesh scene");Object rules=field(game,"rules");float oldX=(Float)field(game,"actorX"),oldY=(Float)field(game,"actorY");int start=(Integer)field(rules,"position");List<?>edges=(List<?>)field(rules,"edges");int next=((Collection<Integer>)edges.get(start)).iterator().next();ui(()->((View)game).getAccessibilityNodeProvider().performAction(next,AccessibilityNodeInfo.ACTION_CLICK,null));waitFor(()->(Integer)field(rules,"position")==next,"maze responds to a step");waitFor(()->(Integer)field(game,"actorPosition")==next,"maze walker animation");waitFor(()->Math.abs((Float)field(game,"actorX")-oldX)+Math.abs((Float)field(game,"actorY")-oldY)>1,"visible maze walker movement");screen("maze-garden");
  finishTo("QuestActivity");getTargetContext().getSharedPreferences("family",0).edit().putString("theme","dark").putBoolean("reduce_motion",true).commit();invoke("menu",new Class[0]);waitFor(()->surface()!=null&&(Long)field(surface(),"renderedFrames")>=1,"dark reduced preview");Button b=find(activity.getWindow().getDecorView(),"Maker World");if(b.getCurrentTextColor()!=Color.WHITE)throw new AssertionError("Dark labels not white");long frame=(Long)field(surface(),"renderedFrames");SystemClock.sleep(400);if((Long)field(surface(),"renderedFrames")>frame+1)throw new AssertionError("Reduced motion renders continuously");screen("toy-dark");ui(()->activity.finish());result.putString("stream","PASS "+captures+" visual flows: animated mesh menus, real Village and legacy aliases, nine direct adventure targets, native studio entry, fish touch motion, illustrated puzzle catalog, maze movement, white dark labels and reduced-motion idle\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL after "+captures+": "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
